# The R source files a roxygen2-generated .Rd file was written from.
#
# roxygen2 records them in a comment block at the top of every file it
# generates:
#
#     % Generated by roxygen2: do not edit by hand
#     % Please edit documentation in R/foo.R, R/bar.R
#
# The wrapped continuation lines that belong to it are chosen by
# `.rd_block_lines()`, which cannot be decided from the text alone.
#
# Each line's own prefix is stripped before the block is joined, so a `%` that
# is part of a filename is left alone.
#
# Returns `character(0)` for a hand-written .Rd, which carries no such comment:
# there the .Rd file is itself the source. Files the comment names but the
# package no longer has are dropped too, so a stale .Rd cannot produce a link
# to a file nobody can open.
.rd_source_files <- function(rd_file, src_dir) {
    if (!fs::file_exists(rd_file)) {
        return(character(0))
    }

    lines <- .readlines(rd_file)

    # roxygen2 writes its own banner first and the backref immediately after,
    # so requiring both in place is what makes this a test for "roxygen2
    # generated this file" rather than a search for a sentence a hand-written
    # .Rd is free to contain anywhere.
    start <- 2L
    header_ok <- length(lines) >= start &&
        grepl("^%\\s*Generated by roxygen2", lines[1]) &&
        grepl("^%\\s*Please edit documentation in", lines[start])
    if (!header_ok) {
        return(character(0))
    }

    block <- sub(
        "^%\\s*Please edit documentation in\\s*",
        "",
        lines[start]
    )

    # `%   ,` is not a shape roxygen2 can produce: it joins the list with ", "
    # and `strwrap()` breaks at a space, so a comma is always carried on the
    # end of the filename before it. A line starting with one is somebody
    # else's comment, whatever the filesystem would say about it.
    candidates <- character(0)
    i <- start + 1
    while (
        i <= length(lines) &&
            grepl("^%\\s{2,}\\S", lines[i]) &&
            !grepl("^%\\s+,", lines[i])
    ) {
        candidates <- c(candidates, sub("^%\\s+", "", lines[i]))
        i <- i + 1
    }

    # A block still ending in a comma -- or one whose first line ended at "in"
    # and named nothing -- is growing whatever the filesystem says, so take
    # those lines before asking.
    while (grepl(",$|^$", block) && length(candidates) > 0) {
        block <- trimws(paste(block, candidates[1]))
        candidates <- candidates[-1]
    }

    kept <- .rd_block_lines(block, candidates, src_dir = src_dir)
    if (kept > 0) {
        block <- paste(c(block, candidates[seq_len(kept)]), collapse = " ")
    }

    files <- trimws(strsplit(block, ",", fixed = TRUE)[[1]])
    files <- files[nzchar(files)]

    Filter(
        function(f) fs::file_exists(fs::path_join(c(src_dir, f))),
        files
    )
}
